"    scheduleSearch: function () {
      var self = this;
      if (this.debounceTimer) {
        clearTimeout(this.debounceTimer);
      }

      var clean = this.query.trim();
      if (!clean) {
        this._searchRequestId = (this._searchRequestId || 0) + 1;
        this.renderResults([]);
        if (this.resultsCount) this.resultsCount.textContent = '';
        return;
      }

      this.debounceTimer = setTimeout(function () {
        self.executeSearch();
      }, 300);
    },

    executeSearch: function () {
      var self = this;
      var cleanQuery = this.query.trim();
      if (!cleanQuery) return;

      if (!global.TmdbClient) {
        console.warn('[SearchViewController] TmdbClient unavailable for search.');
        return;
      }

      this._searchRequestId = (this._searchRequestId || 0) + 1;
      var reqId = this._searchRequestId;

      return global.TmdbClient.searchMulti(cleanQuery, 1).then(function (res) {
        if (reqId !== self._searchRequestId || self.query.trim() !== cleanQuery || !self.query.trim()) {
          return;
        }

        if (!res || res.error) {
          self.renderError();
          return;
        }

        var results = res.results || [];
        var filtered = results.filter(function (item) {
          return item.media_type === 'movie' || item.media_type === 'tv' || item.type === 'movie' || item.type === 'tv' || (!item.media_type && (item.title || item.name));
        });

        self.renderResults(filtered);
        if (self.resultsCount) {
          self.resultsCount.textContent = '(' + filtered.length + ' matches)';
        }
      }).catch(function (err) {
        if (reqId !== self._searchRequestId || self.query.trim() !== cleanQuery || !self.query.trim()) {
          return;
        }
        console.error('[SearchViewController] Multi-search failed:', err);
        self.renderError();
      });
    },"

